<x-admin-layout title="Event & Moderasi"><h1>Event & Moderasi</h1><p class="muted">Tinjau pengajuan dan kelola publikasi kegiatan di seluruh platform.</p><form class="filter-row"><x-field name="q" label="Nama event" :value="request('q')"/><div class="field"><label for="status">Status</label><select id="status" name="status"><option value="">Semua status</option>@foreach(['draft','pending_review','approved','revision_required','suspended'] as $s)<option @selected(request('status')===$s)>{{ $s }}</option>@endforeach</select></div><button class="btn">Cari</button></form><div class="card table-wrap"><table><thead><tr><th>Event / penyelenggara</th><th>Jadwal / paket</th><th>Status</th><th>Moderasi</th></tr></thead><tbody>@forelse($events as $e)<tr><td>{{ $e->title }}<br><span class="hint">{{ $e->organizer->name }} · {{ $e->city }}</span><details><summary>Informasi & posisi</summary><p>{{ $e->description }}</p><p>{{ $e->venue }}</p>@foreach($e->positions as $p)<h3>{{ $p->name }} · kuota {{ $p->quota }}</h3>@foreach($p->questions as $q)<p>{{ $q['text'] }}<br><span class="hint">{{ implode(' / ',$q['options']) }}</span></p>@endforeach @endforeach</details></td><td>{{ $e->starts_at->timezone('Asia/Jakarta')->format('d M Y H.i') }} WIB<br>{{ $e->limits()['name'] }}</td><td><x-badge :status="$e->moderation"/><x-badge :status="$e->publication"/><x-badge :status="$e->lifecycle"/></td><td>@if($e->moderation==='pending_review')<details><summary>Tinjau Pengajuan</summary><form method="post" action="{{ route('admin.review',$e) }}" data-confirm="Simpan hasil verifikasi event?">@csrf<label>Keputusan<select name="decision"><option value="approved">Setujui</option><option value="revision_required">Minta Revisi</option></select></label><label>Catatan (wajib untuk revisi)<input name="note" maxlength="1000"></label><button class="btn">Simpan Verifikasi</button></form></details>@endif<details><summary>{{ $e->publication==='suspended'?'Pulihkan':'Tangguhkan' }} Publikasi</summary><form method="post" action="{{ route('admin.publication',$e) }}" data-confirm="Ubah publikasi event ini?">@csrf<input type="hidden" name="action" value="{{ $e->publication==='suspended'?'restore':'suspend' }}"><label>Alasan<input name="reason" maxlength="500" required></label><button class="btn secondary">Simpan Publikasi</button></form></details>@if($e->moderation_note)<p class="hint">{{ $e->moderation_note }}</p>@endif</td></tr>@empty<tr><td colspan="4">Tidak ada event sesuai filter.</td></tr>@endforelse</tbody></table></div>{{ $events->links() }}</x-admin-layout>